@section('scripts')<script>function calc(){let s=document.querySelector('#wasteSelect');let p=s?.selectedOptions[0]?.dataset.price||0;let w=document.querySelector('#weightInput')?.value||0;document.querySelector('#totalPreview').value='Rp '+new Intl.NumberFormat('id-ID').format(p*w)}document.querySelector('#wasteSelect')?.addEventListener('change',calc);document.querySelector('#weightInput')?.addEventListener('input',calc)</script>@endsection
